import { Project } from '../../src'
import { path } from '@servicenow/sdk-build-core'

describe('Cross Scope/Entity Interop Test Suite', () => {
    test('CrossScope Entity serialization test', async () => {
        const project = new Project({
            rootDir: path.resolve(__dirname, 'project'),
        })

        const newFile = project.findFile('CrossScope.now.ts')
        expect(newFile).toBeDefined()

        const records = await newFile.getRecords()
        expect(records.query()).toHaveLength(2)

        const crossScopeRecord1 = records.get('sys_scope_privilege', '78d96cf')
        expect(crossScopeRecord1).toBeDefined()

        const crossScopeRecord2 = records.get('sys_scope_privilege', '78d96ef')
        expect(crossScopeRecord2).toBeDefined()

        const output = await newFile.getOutput()
        expect(output).toHaveLength(2)

        const crossScopeXML1 = output.find((xml) => xml.path.endsWith('sys_scope_privilege_78d96cf.xml'))
        const crossScopeXML2 = output.find((xml) => xml.path.endsWith('sys_scope_privilege_78d96ef.xml'))

        // validate xml generated

        expect(crossScopeXML1?.content).toContain('<sys_id>78d96cf</sys_id>')
        expect(crossScopeXML1?.content).toContain('<status>allowed</status>')

        expect(crossScopeXML2?.content).toContain('<sys_id>78d96ef</sys_id>')
        expect(crossScopeXML2?.content).toContain('<status>requested</status>')
    })

    test('CrossScope Entity transform test', async () => {
        const project = new Project({
            rootDir: path.resolve(__dirname, 'project'),
        })

        await project.transform({
            path: 'sys_scope_privilege_1.xml',
            content: `<?xml version="1.0"?><record_update>
                <sys_scope_privilege action="INSERT_OR_UPDATE">
                    <sys_id>8d7bf19691064a39bc32937a009d92ed</sys_id>
                    <sys_scope display_value="x_test">11112222333344445555666677778888</sys_scope>
                    <source_scope>11112222333344445555666677778888</source_scope>
                    <target_scope>global</target_scope>
                    <target_name>Table Type</target_name>
                    <status>requested</status>
                    <target_type>sys_db_object</target_type>
                    <operation>read</operation>
                </sys_scope_privilege>
            </record_update>`,
        })

        const fluentFile = project.findFile((f) => f.getPath().endsWith('sys_scope_privilege_1.now.ts'))
        expect(fluentFile).toBeDefined()
        expect(fluentFile.getContent()).toBe(`import { CrossScopePrivilege } from '@servicenow/sdk/core'

CrossScopePrivilege({
    $id: Now.ID['8d7bf19691064a39bc32937a009d92ed'],
    operation: 'read',
    status: 'requested',
    targetName: 'Table Type',
    targetScope: 'global',
    targetType: 'sys_db_object',
})
`)
    })
})
